import fixtureJson from '../../oracles/fixtures/space-time-statistics.json';

type MoranReference = {I: number[]; pSim: number[]; quadrants: number[]};

/**
 * esda 2.10.0, numpy and scipy reference of the space-time statistics, generated by
 * `test/oracles/space-time-statistics.py`: 40 cells, 7 periods (period-major lists), 5 nearest
 * neighbors (row standardized), seed 12345, 9999 permutations.
 */
export type SpaceTimeStatisticsReference = {
  n: number;
  k: number;
  periods: number;
  period: number;
  cube: number[][];
  second: number[][];
  neighbors: number[][];
  permutations: number;
  moran: Record<
    string,
    {laggedInward: MoranReference; laggedOutward: MoranReference; differential: MoranReference}
  >;
  crossCorrelation: {
    lags: number[];
    correlations: number[];
    fisherPValues: number[];
    exactPValues: number[];
    pairCounts: number[];
    adjustedFisherBH: number[];
  };
};

const fixture = fixtureJson as unknown as {
  generator: string;
  versions: Record<string, string>;
  reference: SpaceTimeStatisticsReference;
};

/** The reference values. */
export const SPACE_TIME_STATISTICS_REFERENCE: SpaceTimeStatisticsReference = fixture.reference;
/** Library versions that produced the fixture. */
export const SPACE_TIME_STATISTICS_VERSIONS = fixture.versions;
